T = {}
def t(key, fam, label, what, points, hub=None):
    T[key] = dict(family=fam, label=label, what=what, points=points, hub=hub)

# ---- vets
t('vet','vet','a vet',"A vet diagnoses and treats illness and injury in animals, carries out surgery, prescribes medicines and provides preventive care such as vaccinations, parasite control and neutering.",["Registering before your pet is unwell saves time when something goes wrong.","Ask how the practice covers nights and weekends; many use a dedicated out-of-hours provider.","Preventive health plans can spread the cost of routine care, but check what they include."])
t('24-hour-vet','vet','a 24-hour vet',"A 24-hour vet service has a vet available around the clock, either at a hospital with staff on site overnight or through a dedicated out-of-hours clinic that covers several day practices.",["Find out now which clinic covers your area at night, before you need it.","Out-of-hours care usually costs more than daytime appointments because of staffing.","Ask whether overnight patients are monitored by a vet or nurse on site all night."])
t('emergency-vet','vet','an emergency vet',"Emergency vets handle urgent problems such as road accidents, poisoning, breathing difficulty, bloat, collapse and difficult births, often at dedicated emergency clinics.",["In a genuine emergency, phone ahead so the team can prepare, and travel straight there.","Bring packaging of anything your pet may have swallowed.","Emergency clinics usually send records back to your normal practice afterwards."])
t('animal-hospital','vet','an animal hospital',"Animal hospitals are larger veterinary centres with inpatient wards, advanced imaging, dedicated theatres and often specialists, and many accept referrals from first-opinion practices.",["Most cases reach a hospital through a referral from your own vet.","Hospitals can offer CT, MRI, specialist surgery and intensive care.","Ask whether your insurer needs to approve referral treatment first."])
t('private-vet','vet','an independent private vet',"Independent practices are owned by the vets who work there rather than by a large group, and some owners prefer the continuity and personal approach this can bring.",["Ask whether you will usually see the same vet each visit.","Check the practice's out-of-hours arrangements, which may be shared.","Independent and group practices are regulated in the same way by the RCVS."])
t('small-animal-vet','vet','a small animal vet',"Small animal vets focus on companion animals such as dogs, cats, rabbits and small mammals, and most high-street practices are small animal practices.",["Check that the practice is comfortable with your particular species.","Ask about vaccination schedules and preventive health plans.","Rabbits and small mammals benefit from vets with specific interest and experience."])
t('dog-vet','vet','a vet for your dog',"Dogs need vaccinations, parasite control, dental care and regular health checks, and breeds have their own common problems, from joint conditions to breathing issues in flat-faced breeds.",["Ask about breed-specific health screening.","Puppy packages often bundle first vaccinations, microchipping and a health check.","Regular dental checks can prevent painful problems later in life."])
t('cat-vet','vet','a cat-friendly vet',"Cats often find vet visits stressful, and practices accredited as cat-friendly use separate waiting areas, gentle handling and quieter consulting rooms to reduce that stress.",["Ask whether the practice holds Cat Friendly Clinic accreditation.","A covered carrier and a familiar blanket help reduce stress.","Cats hide illness well, so regular checks matter as they age."])
t('rabbit-vet','vet','a rabbit vet',"Rabbits need specialist knowledge of their teeth, gut and anaesthetic care, plus vaccinations against myxomatosis and RHD strains.",["Ask how many rabbits the practice sees and whether a vet has a particular interest.","Gut stasis can become an emergency quickly; know who to call.","Dental problems are common and need experienced handling."])
t('exotic-vet','vet','an exotic animal vet',"Exotic vets treat reptiles, birds, small mammals, amphibians and other non-traditional pets that need specialist knowledge of husbandry, diet and medicine.",["Not every practice sees exotic species, so check before an emergency arises.","Many exotic problems relate to environment and diet; bring photos of your set-up.","Some vets hold RCVS certificates or specialist status in zoological medicine."])
t('exotic-pet-vet','vet','a vet for exotic pets',"Pets such as snakes, lizards, parrots, ferrets and chinchillas need vets familiar with their anatomy, normal behaviour and specific health risks.",["Ask which species the vets are confident with.","Bring details of temperature, lighting and diet for reptiles.","Transport small exotics in secure, temperature-appropriate containers."])
t('reptile-vet','vet','a reptile vet',"Reptile vets understand how temperature, UV lighting, humidity and diet affect snakes, lizards and tortoises, and many illnesses trace back to husbandry.",["Note vivarium temperatures and lighting before the appointment.","Tortoises benefit from checks before and after hibernation.","Ask whether the practice can perform reptile anaesthesia and imaging."])
t('bird-vet','vet','an avian vet',"Avian vets treat pet birds, poultry and birds of prey, and understand how quickly sick birds can deteriorate.",["Birds hide illness, so fluffed feathers or reduced eating deserve prompt attention.","Bring the bird in its cage if possible, with droppings visible.","Ask whether the practice has experience with your type of bird."])
t('equine-vet','vet','an equine vet',"Equine vets treat horses, ponies and donkeys, often on the yard as well as at clinics, covering lameness, colic, dentistry, vaccinations and pre-purchase examinations.",["Ask how emergency colic calls are covered at night.","Pre-purchase vettings follow a standard format; agree which stages you need.","Check whether the practice has a clinic for imaging or surgery."])
t('horse-vet','vet','a horse vet',"Horse owners need a vet who can visit the yard for routine care and respond quickly to emergencies such as colic, wounds and lameness.",["Agree routine visit days with others on your yard to share call-out costs.","Keep a basic first aid kit and your vet's emergency number at the yard.","Ask about dental and vaccination reminders."])
t('farm-vet','vet','a farm vet',"Farm vets work with cattle, sheep, pigs and other livestock on herd health, fertility, disease control, TB testing and welfare.",["Herd health plans help prevent disease and support farm assurance schemes.","Ask whether the practice is approved for official TB testing in your area.","Discuss how emergency calvings and lambings are covered."])
t('home-visit-vet','vet','a vet who does home visits',"Home visit vets see animals in their own home, which can suit nervous pets, multi-pet households, owners without transport and peaceful end-of-life care.",["Home visits suit consultations, vaccinations and euthanasia; surgery still needs a clinic.","Ask what equipment the vet brings.","Check the visiting area and how quickly they can come."])
t('vet-dentist','vet','a veterinary dentist',"Veterinary dentistry covers scaling, extractions, treatment of fractured teeth and oral disease, usually under general anaesthetic with dental X-rays.",["Ask whether the practice has dental X-ray equipment.","Bad breath, drooling and pawing at the mouth are common signs of dental pain.","Complex cases may be referred to a vet with advanced dental training."])

# ---- accountants
t('accountant','accountant','an accountant',"An accountant prepares accounts and tax returns, keeps you compliant with HMRC and Companies House, and can advise on tax, cash flow and business decisions.",["Agree exactly which returns and filings the fee covers.","Ask how the practice handles Making Tax Digital.","A good accountant should help you plan, not only file."])
t('acca-accountant','accountant','an ACCA chartered certified accountant',"ACCA members are chartered certified accountants who have passed a demanding qualification, follow ACCA's ethics code and complete continuing professional development.",["You can check membership through the ACCA register.","Firms offering public practice services need an ACCA practising certificate.","ACCA members can work with sole traders through to large companies."])
t('cima-accountant','accountant','a CIMA management accountant',"CIMA members are chartered management accountants, specialising in budgeting, forecasting, costing and decision support rather than only compliance work.",["CIMA accountants suit businesses wanting better management information.","Some also hold practising certificates for compliance work.","Ask for examples of management reports they produce."])
t('chartered-accountant','accountant','a chartered accountant',"Chartered accountants are members of ICAEW, ICAS or Chartered Accountants Ireland, and many firms are also authorised to carry out statutory audits.",["Check the firm's status on the institute's directory.","Chartered firms suit audits, complex groups and specialist tax work.","Ask whether a partner reviews your work."])
t('certified-accountant','accountant','a certified accountant',"Certified accountants usually hold the ACCA chartered certified qualification, which is widely recognised for practice, tax and business advisory work.",["Ask which body awarded the qualification.","Check professional indemnity insurance.","Ask about experience with your type of business."])
t('business-accountant','accountant','an accountant for your business',"Business accountants handle year-end accounts, tax returns, VAT and payroll, and many offer management accounts and planning that help owners make decisions.",["Monthly or quarterly contact can catch problems early.","Ask about software integration with your bank and invoicing.","Plan tax payments ahead to avoid cash-flow surprises."])
t('company-accountant','accountant','an accountant for your company',"Company accountants prepare statutory accounts, corporation tax returns and confirmation statements, and advise directors on salary, dividends and expenses.",["Directors have legal duties around filing deadlines; agree who tracks them.","Ask about advice on director remuneration.","Check whether payroll and VAT are included."])
t('limited-company-accountant','accountant','a limited company accountant',"Limited companies must file accounts with Companies House and a corporation tax return with HMRC, and directors often need personal tax returns too.",["Ask whether director Self Assessment returns are included.","Agree who submits the confirmation statement.","Plan dividends and salary with your accountant before year end."])
t('corporate-accountant','accountant','a corporate accountant',"Corporate accountants work with larger companies and groups on consolidated accounts, audit preparation, corporate tax and transactions.",["Ask about experience with group structures.","Audit-exempt companies may still benefit from assurance work.","Check how the firm handles international aspects."])
t('commercial-accountant','accountant','a commercial accountant',"Commercial accountants focus on improving the performance of a business through budgeting, pricing, margin analysis and forecasting.",["Useful when growth is outpacing your financial controls.","Ask for examples of decisions their analysis has supported.","Some work part-time as a finance director."])
t('personal-accountant','accountant','a personal accountant',"Personal accountants help individuals with Self Assessment, capital gains, rental income, pensions and other personal tax matters.",["Bring P60s, investment statements and rental figures.","Ask whether they can deal with HMRC on your behalf.","Plan for payments on account."])
t('self-assessment-accountant','accountant','a Self Assessment accountant',"Self Assessment accountants prepare and file personal tax returns for the self-employed, landlords, company directors and people with untaxed income.",["The online filing deadline is 31 January after the tax year ends.","Engaging early gives time to check claims and reliefs.","Ask how payments on account will affect your cash flow."])
t('affordable-accountant','accountant','an accountant at a fair price',"Many people want competent accountancy without paying for services they do not need, and well-defined packages help keep the scope matched to the work.",["Tidy records reduce the time an accountant needs.","Fixed fees give certainty; check what is excluded.","Cheapest is not always best value if mistakes cost penalties."])
t('cheap-accountant','accountant','a low-cost accountant',"For simple tax affairs, low-cost accountancy can work well, as long as the accountant is properly supervised and the scope is clear.",["Check AML supervision and professional membership.","Ask what happens if HMRC sends an enquiry.","Make sure you get copies of everything filed."])
t('local-accountant','accountant','a local accountant',"Some clients prefer an accountant they can meet face to face, who knows local businesses and can visit when needed.",["Local knowledge helps with sectors common in your area.","Many local practices also work remotely.","Ask whether meetings are included in the fee."])
t('online-accountant','accountant','an online accountant',"Online accountants work through cloud software, video calls and secure portals, often with fixed monthly fees.",["Check response times and whether you have a named contact.","Make sure your software is compatible.","Online firms should be supervised like any other."])
t('cloud-accountant','accountant','a cloud accountant',"Cloud accountants use software such as Xero, QuickBooks or FreeAgent to give real-time visibility of your numbers, with bank feeds and digital receipts.",["Ask which platforms they are certified in.","Good set-up saves time later.","Real-time data helps with forecasting."])
t('contractor-accountant','accountant','a contractor accountant',"Contractor accountants support freelancers and contractors working through limited companies or umbrella arrangements, including IR35 assessments.",["Ask whether contract reviews for IR35 are included.","Check expenses rules for travel and subsistence.","Plan for gaps between contracts."])
t('freelance-accountant','accountant','an accountant for freelancers',"Freelancers often juggle irregular income, multiple clients and allowable expenses, and an accountant helps keep tax payments predictable.",["Set aside a share of each payment for tax.","Keep receipts digitally from day one.","Ask whether trading as a company would suit you."])
t('freelancer-accountant','accountant','a freelancer accountant',"An accountant used to working with freelancers can help with Self Assessment, VAT thresholds and the choice between sole trader and limited company.",["Ask about Making Tax Digital for Income Tax.","Check how they deal with income from abroad or platforms.","Get advice before you cross the VAT threshold."])
t('ecommerce-accountant','accountant','an e-commerce accountant',"E-commerce accountants understand marketplace fees, stock, multi-currency sales and VAT on online sales into the UK and EU.",["Ask about integrations with your sales platforms.","VAT on overseas sales can be complex.","Stock records affect profit and tax."])
t('amazon-seller-accountant','accountant','an accountant for Amazon sellers',"Amazon sellers deal with settlement reports, fees, refunds, stock held in fulfilment centres and VAT across markets, which need careful reconciliation.",["Ask about experience reconciling Amazon settlements.","Check VAT registration needs if stock is held abroad.","Track cost of goods carefully."])
t('crypto-accountant','accountant','a crypto accountant',"Crypto accountants calculate gains and income on cryptoassets using HMRC's pooling rules and help report them correctly.",["Export complete transaction histories from every exchange and wallet.","Staking and airdrops can create income tax.","HMRC can obtain information from exchanges."])
t('construction-accountant','accountant','a construction accountant',"Construction accountants understand the Construction Industry Scheme, retentions, stage payments and the VAT domestic reverse charge.",["Ask about CIS returns and refunds.","Retentions affect cash flow and accounts.","The reverse charge changes how VAT invoices work."])
t('cis-accountant','accountant','a CIS accountant',"CIS accountants help contractors file monthly returns and subcontractors reclaim tax deducted under the Construction Industry Scheme.",["Keep payment and deduction statements.","Late CIS returns attract penalties.","Limited company subcontractors can offset deductions."])
t('charity-accountant','accountant','a charity accountant',"Charity accountants prepare accounts under the Charities SORP, carry out independent examinations or audits and advise trustees on reporting and Gift Aid.",["Thresholds decide whether you need an independent examination or audit.","Ask about Charity Commission filing.","Restricted funds need careful tracking."])
t('farm-accountant','accountant','a farm accountant',"Farm accountants understand agricultural property relief, subsidies and payments, herd basis, averaging of profits and diversification.",["Ask about averaging for fluctuating profits.","Succession planning needs early advice.","Diversification can change tax treatment."])
t('restaurant-accountant','accountant','a restaurant accountant',"Restaurant accountants work with tips and troncs, stock, VAT on food and drink, payroll for shift staff and tight margins.",["Troncs have specific payroll rules.","VAT on hot food and takeaway can be complex.","Weekly figures help control costs."])
t('medical-accountant','accountant','a medical accountant',"Medical accountants work with doctors and healthcare professionals on NHS pensions, locum income, private practice and partnership accounts.",["NHS pension annual allowance issues need specialist help.","Locums often have several income sources.","Ask about AISMA membership."])
t('dentist-accountant','accountant','an accountant for dentists',"Accountants for dentists understand associate and principal arrangements, NHS contracts, practice purchases and NHS pension issues.",["Ask about NASDA membership or dental experience.","Associates are usually self-employed.","Practice purchases need due diligence."])
t('landlord-accountant','accountant','an accountant for landlords',"Landlord accountants prepare rental income accounts, apply allowable expenses and advise on mortgage interest restrictions and incorporation.",["Keep records for each property.","Finance costs get a basic-rate tax credit for individuals.","Ask about Making Tax Digital for landlords."])
t('landlord-tax-accountant','accountant','a landlord tax accountant',"Landlord tax accountants focus on income tax, capital gains on disposals and the choice between personal and company ownership.",["Capital gains on residential property have their own reporting deadline.","Incorporation can trigger tax costs.","Joint ownership affects how income is split."])
t('portfolio-landlord-accountant','accountant','an accountant for portfolio landlords',"Portfolio landlords with several properties need accounts by property, lender-ready figures and longer-term structure planning.",["Lenders may ask for business plans and cash-flow forecasts.","Consider whether a company structure suits future purchases.","Track capital and revenue spending separately."])
t('property-accountant','accountant','a property accountant',"Property accountants work with landlords, developers and investors on rental income, gains, development profits and SDLT considerations.",["Development and investment are taxed differently.","Ask about SDLT and VAT on commercial property.","Structure matters before you buy."])
t('property-developer-accountant','accountant','an accountant for property developers',"Developers need accounts that treat property as trading stock, plus advice on VAT, CIS, finance costs and project companies.",["Special purpose vehicles are common for each project.","VAT on new builds and conversions has specific rules.","Profit is taxed when units are sold."])
t('partnership-accountant','accountant','a partnership accountant',"Partnership accountants prepare partnership accounts and returns and allocate profits correctly to each partner's tax return.",["The partnership agreement affects profit shares.","Each partner still files their own return.","Ask about basis period reform effects."])
t('llp-accountant','accountant','an LLP accountant',"Limited liability partnerships file accounts at Companies House and a partnership return with HMRC, with members taxed individually.",["Salaried member rules can affect tax status.","Members need individual Self Assessment returns.","Ask about LLP SORP if applicable."])
t('expat-accountant','accountant','an expat accountant',"Expat accountants help people living abroad, or returning to the UK, with residence status, split-year treatment and UK income such as rental property.",["The Statutory Residence Test decides your UK tax status.","Double tax treaties can prevent being taxed twice.","Non-residents selling UK property must report gains."])
t('non-resident-accountant','accountant','an accountant for non-residents',"Non-residents with UK income, especially rent, need to deal with the Non-Resident Landlord Scheme, UK returns and gains on UK property.",["Register for the Non-Resident Landlord Scheme to receive rent gross.","UK property disposals must be reported within a short deadline.","Ask about treaty relief."])
t('corporation-tax-accountant','accountant','a corporation tax accountant',"Corporation tax accountants calculate taxable profits, apply reliefs such as capital allowances and R&D, and file CT600 returns.",["Corporation tax is usually due nine months and one day after year end.","Ask about R&D relief eligibility.","Marginal relief applies between thresholds."])
t('forensic-accountant','accountant','a forensic accountant',"Forensic accountants investigate financial records for disputes, fraud, insurance claims, divorce and litigation, and may act as expert witnesses.",["Expert witnesses have duties to the court.","Ask about experience in your type of dispute.","Early involvement helps preserve evidence."],hub='forensic-accountants')
t('best-accountant','accountant','a highly rated accountant',"The best accountant for you is one with relevant experience, clear fees, good communication and proper supervision, not simply the biggest name.",["Read engagement letters closely.","Ask for references from similar clients.","Judge responsiveness during the first contact."])
